-- Read-only metadata/count evidence; never exports participant identities.
SELECT jsonb_build_object('observed_at',now(),'settings',(SELECT to_jsonb(s) FROM private.hhl_settings s WHERE singleton),'registrations',(SELECT count(*) FROM private.hhl_registrations),'jobs',(SELECT count(*) FROM private.hhl_jobs),'leased_jobs',(SELECT count(*) FROM private.hhl_jobs WHERE state='leased'),'attendance',(SELECT count(*) FROM private.hhl_attendance),'versions',(SELECT jsonb_agg(version ORDER BY version) FROM supabase_migrations.schema_migrations WHERE version IN ('20261020141529','20261020193400','20261020201535','20261020215108','20261021144712')),'functions_fingerprint',(SELECT md5(string_agg(n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')'||pg_get_functiondef(p.oid)||coalesce(p.proacl::text,'')||p.proowner::text||coalesce(p.proconfig::text,''),E'\n' ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','private') AND p.prokind='f'),'policy_fingerprint',(SELECT md5(string_agg(to_jsonb(p)::text,E'\n' ORDER BY schemaname,tablename,policyname)) FROM pg_policies p WHERE schemaname IN ('public','private')),'table_fingerprint',(SELECT md5(string_agg(n.nspname||'.'||c.relname||c.relrowsecurity::text||c.relforcerowsecurity::text||coalesce(c.relacl::text,''),E'\n' ORDER BY n.nspname,c.relname)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private') AND c.relkind IN ('r','v','p')),'role_fingerprint',(SELECT md5(string_agg(row_to_json(r)::text,E'\n' ORDER BY rolname)) FROM pg_roles r)) AS evidence;
